function firstNonEmptyString(...values) {
  for (const value of values) {
    if (typeof value === 'string' && value.trim().length > 0) {
      return value.trim();
    }
  }
  return '';
}

function humanizeModelKey(modelKey) {
  if (typeof modelKey !== 'string' || modelKey.trim().length === 0) return '';

  const normalized = modelKey.trim().replace(/[_-]+/g, ' ');
  return normalized
    .split(/\s+/)
    .filter(Boolean)
    .map((part) => {
      if (/^\d+(?:\.\d+)?$/.test(part)) return part;
      if (/^[A-Z0-9]+$/.test(part)) return part;
      return part.charAt(0).toUpperCase() + part.slice(1).toLowerCase();
    })
    .join(' ');
}

export function getModelDisplayName(modelKey, fallbackName = '') {
  const key = firstNonEmptyString(modelKey);
  if (!key) return firstNonEmptyString(fallbackName);
  if (MODEL_DISPLAY_NAME_OVERRIDES.has(key)) return MODEL_DISPLAY_NAME_OVERRIDES.get(key);
  return firstNonEmptyString(fallbackName) || humanizeModelKey(key) || key;
}

export function normalizeModelEntry(entry) {
  if (!entry || typeof entry !== 'object') return entry;

  const modelKey = firstNonEmptyString(entry.model_key, entry.modelKey, entry.id);
  const displayName = getModelDisplayName(modelKey, firstNonEmptyString(entry.title, entry.label, entry.name));

  return {
    ...entry,
    model_key: modelKey || entry.model_key || entry.modelKey || entry.id || '',
    title: firstNonEmptyString(entry.title, displayName),
    label: firstNonEmptyString(entry.label, displayName),
    name: firstNonEmptyString(entry.name, displayName),
    model_name: displayName,
    display_name: displayName,
  };
}

const STATUS_MAP = {
  waiting: 'waiting',
  WAITING: 'waiting',
  pending: 'waiting',
  PENDING: 'waiting',
  processing: 'processing',
  PROCESSING: 'processing',
  running: 'processing',
  RUNNING: 'processing',
  succeed: 'completed',
  SUCCEED: 'completed',
  success: 'completed',
  SUCCESS: 'completed',
  failed: 'failed',
  FAILED: 'failed',
};

const CONTENT_STATUS_MAP = {
  'text-success': 'text-success',
  'text-fail': 'text-fail',
  'audio-success': 'audio-success',
  'audio-fail': 'audio-fail',
};

export function normalizeStatus(raw) {
  const mapped = STATUS_MAP[raw];
  if (!mapped) {
    process.stderr.write(`[weryai] Warning: unknown task_status "${raw}", treating as "unknown"\n`);
    return 'unknown';
  }
  return mapped;
}

export function normalizeContentStatus(raw) {
  if (typeof raw !== 'string' || !raw.trim()) return null;
  const normalized = raw.trim().toLowerCase();
  return CONTENT_STATUS_MAP[normalized] || normalized;
}

export function toPhase(normalizedStatus) {
  if (normalizedStatus === 'completed') return 'completed';
  if (normalizedStatus === 'failed') return 'failed';
  return 'running';
}

export function normalizeTaskResult(data) {
  if (Array.isArray(data)) {
    return pickSingleTask(data.map(normalizeSingleTask));
  }
  return normalizeSingleTask(data);
}

export function normalizeTaskCollection(data) {
  if (Array.isArray(data)) {
    return data.map(normalizeSingleTask);
  }
  return [normalizeSingleTask(data)];
}

export function hasTaskOutput(task, outputKey) {
  const value = task?.[outputKey];
  return Array.isArray(value) ? value.length > 0 : Boolean(value);
}

export function normalizeBatchPhase(tasks, { outputKey } = {}) {
  const valid = tasks.filter(Boolean);
  if (valid.length === 0) return 'unknown';
  const allDone = valid.every((task) => task.taskStatus === 'completed' || task.taskStatus === 'failed');
  if (!allDone) return 'running';
  const anyFailed = valid.some((task) => task.taskStatus === 'failed');
  const anyMissingOutput = outputKey
    ? valid.some((task) => task.taskStatus === 'completed' && !hasTaskOutput(task, outputKey))
    : false;
  if (anyFailed || anyMissingOutput) return 'failed';
  return 'completed';
}

function normalizeSingleTask(task) {
  if (!task) {
    return {
      taskId: null,
      rawStatus: 'unknown',
      taskStatus: 'unknown',
      images: null,
      videos: null,
      audios: null,
      lyrics: null,
      coverUrl: null,
      msg: null,
    };
  }

  const rawStatus = task.task_status ?? task.taskStatus ?? 'unknown';
  const status = normalizeStatus(rawStatus);
  const contentStatus = normalizeContentStatus(
    task.content_status ?? task.contentStatus ?? task.output?.content_status,
  );
  const images = normalizeArray(task.images ?? task.output?.images);
  const videos = normalizeArray(task.videos ?? task.output?.videos);
  const audios = normalizeArray(task.audios ?? task.output?.audios);
  const lyrics = normalizeString(task.lyrics ?? task.output?.lyrics);
  const coverUrl = normalizeString(task.cover_url ?? task.coverUrl ?? task.output?.cover_url);
  const scripts = normalizeScripts(task.scripts ?? task.output?.scripts ?? task.script ?? task.output?.script);

  return {
    taskId: task.task_id ?? task.taskId ?? null,
    rawStatus,
    taskStatus: status,
    contentStatus,
    images,
    videos,
    audios,
    lyrics,
    coverUrl,
    scripts,
    msg: task.msg ?? null,
  };
}

function normalizeArray(value) {
  return Array.isArray(value) && value.length > 0 ? value : null;
}

function normalizeString(value) {
  return typeof value === 'string' && value.trim() ? value : null;
}

function normalizeScripts(value) {
  if (!Array.isArray(value) || value.length === 0) return null;
  return value.map((entry) => {
    if (!entry || typeof entry !== 'object') return entry;
    return {
      speakerId: entry.speaker_id ?? entry.speakerId ?? null,
      speakerName: entry.speaker_name ?? entry.speakerName ?? null,
      content: typeof entry.content === 'string' ? entry.content : null,
    };
  });
}

function pickSingleTask(tasks) {
  if (!Array.isArray(tasks) || tasks.length === 0) {
    return normalizeSingleTask(null);
  }
  return tasks[0];
}

import { createClient } from './client.js';
import { formatApiError, formatNetworkError, isApiSuccess } from './errors.js';
import { hasTaskOutput, normalizeBatchPhase, normalizeTaskCollection, normalizeTaskResult, toPhase } from './normalize.js';

export async function executeStatus(input, ctx, options) {
  const { outputKey, outputLabel, allowBatch = false } = options;
  const taskId = input.taskId || input['task-id'] || input.task_id;
  const batchId = input.batchId || input['batch-id'] || input.batch_id;

  if (!taskId && !(allowBatch && batchId)) {
    return {
      ok: false,
      phase: 'failed',
      errorCode: 'VALIDATION',
      errorCategory: 'validation',
      errorTitle: 'Missing identifier',
      retryable: false,
      field: allowBatch && !taskId ? 'task_id|batch_id' : 'task_id',
      hint: allowBatch ? 'Provide either a task ID or a batch ID.' : 'Provide a task ID and retry.',
      errorMessage: allowBatch
        ? 'Either --task-id or --batch-id is required.'
        : 'The status script requires `--task-id <task-id>`.',
    };
  }

  const client = createClient(ctx);
  if (allowBatch && batchId) return queryBatch(client, batchId, { outputKey, outputLabel });
  return queryTask(client, taskId, { outputKey, outputLabel });
}

async function queryTask(client, taskId, options) {
  const { outputKey, outputLabel } = options;

  let res;
  try {
    res = await client.get(`/v1/generation/${taskId}/status`, { retries: 3 });
  } catch (err) {
    return formatNetworkError(err);
  }

  if (!isApiSuccess(res)) {
    return formatApiError(res);
  }

  const task = normalizeTaskResult(res.data);
  const phase = toPhase(task.taskStatus);
  const missingOutputs = phase === 'completed' && !hasTaskOutput(task, outputKey);
  return {
    ok: phase !== 'failed' && !missingOutputs,
    phase: missingOutputs ? 'failed' : phase,
    batchId: null,
    taskIds: task.taskId ? [task.taskId] : [],
    taskId: task.taskId,
    taskStatus: task.taskStatus,
    [outputKey]: task[outputKey],
    lyrics: task.lyrics,
    coverUrl: task.coverUrl,
    balance: null,
    errorCode: phase === 'failed' || missingOutputs ? 'TASK_FAILED' : null,
    errorCategory: phase === 'failed' || missingOutputs ? 'task' : null,
    errorTitle: phase === 'failed'
      ? 'Task failed'
      : missingOutputs
        ? `Missing ${outputLabel} output`
        : null,
    retryable: phase === 'failed' || missingOutputs ? false : null,
    field: null,
    hint: phase === 'failed' || missingOutputs ? 'Check the task payload and existing task status before submitting a new job.' : null,
    errorMessage: missingOutputs
      ? `Task reached a completed state but returned no ${outputLabel} URLs.`
      : phase === 'failed'
        ? (task.msg || 'Task failed')
        : null,
  };
}

async function queryBatch(client, batchId, options) {
  const { outputKey, outputLabel } = options;

  let res;
  try {
    res = await client.get(`/v1/generation/batch/${batchId}/status`, { retries: 3 });
  } catch (err) {
    return formatNetworkError(err);
  }

  if (!isApiSuccess(res)) {
    return formatApiError(res);
  }

  const tasks = normalizeTaskCollection(res.data);
  const phase = normalizeBatchPhase(tasks, { outputKey });

  return {
    ok: phase !== 'failed',
    phase,
    batchId,
    tasks,
    errorCode: phase === 'failed' ? 'TASK_FAILED' : null,
    errorCategory: phase === 'failed' ? 'task' : null,
    errorTitle: phase === 'failed' ? 'Batch failed' : null,
    retryable: phase === 'failed' ? false : null,
    field: null,
    hint: phase === 'failed' ? 'Inspect individual task states in the batch before retrying.' : null,
    errorMessage: phase === 'failed'
      ? `One or more tasks in the batch failed or returned no ${outputLabel} URLs.`
      : null,
  };
}

import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { formatApiError, isApiSuccess } from './errors.js';

export const DEFAULT_UPLOAD_API_PATH = '/v1/generation/upload-file';
export const DEFAULT_UPLOAD_MAX_BYTES = 500 * 1024 * 1024;

const ALLOWED_UPLOAD_EXTS = new Set([
  // image
  '.jpg', '.jpeg', '.png', '.webp', '.gif', '.bmp', '.tiff', '.tif',
  // video
  '.mp4', '.mov', '.m4v', '.webm', '.avi', '.mkv',
  // audio
  '.mp3', '.wav', '.m4a', '.aac', '.flac', '.ogg',
  // text and structured text
  '.txt', '.md', '.json', '.csv', '.srt', '.vtt', '.xml', '.yaml', '.yml',
]);

const BLOCKED_UPLOAD_EXTS = new Set([
  '.exe', '.dll', '.bat', '.cmd', '.com', '.msi', '.scr', '.ps1', '.sh',
  '.apk', '.ipa', '.bin', '.jar',
]);

export function isPublicHttpsUrl(value) {
  if (typeof value !== 'string' || value.trim().length === 0) return false;
  try {
    const url = new URL(value);
    return url.protocol === 'https:';
  } catch {
    return false;
  }
}

export function isRemoteUrl(value) {
  if (typeof value !== 'string' || value.trim().length === 0) return false;
  try {
    const url = new URL(value);
    return url.protocol === 'https:' || url.protocol === 'http:';
  } catch {
    return false;
  }
}

export function normalizeLocalFilePath(value) {
  if (typeof value !== 'string' || value.trim().length === 0) return null;
  if (value.startsWith('file://')) {
    return fileURLToPath(new URL(value));
  }
  return path.resolve(value);
}

export function inferMimeTypeByExtension(filePath) {
  const ext = path.extname(filePath).toLowerCase();
  if (ext === '.jpg' || ext === '.jpeg') return 'image/jpeg';
  if (ext === '.png') return 'image/png';
  if (ext === '.webp') return 'image/webp';
  if (ext === '.gif') return 'image/gif';
  if (ext === '.bmp') return 'image/bmp';
  if (ext === '.tiff' || ext === '.tif') return 'image/tiff';
  if (ext === '.mp4') return 'video/mp4';
  if (ext === '.mov') return 'video/quicktime';
  if (ext === '.mp3') return 'audio/mpeg';
  if (ext === '.wav') return 'audio/wav';
  if (ext === '.txt') return 'text/plain';
  if (ext === '.md') return 'text/markdown';
  if (ext === '.json') return 'application/json';
  return 'application/octet-stream';
}

function extractUploadUrl(res) {
  const list = res?.data?.object_url_list;
  if (Array.isArray(list) && typeof list[0] === 'string' && list[0].trim()) {
    return list[0].trim();
  }
  return null;
}

function makeUploadBatchNo(prefix = 'core-upload') {
  return `${prefix}-${Date.now()}`;
}

function formatBytes(bytes) {
  const mb = bytes / (1024 * 1024);
  return `${mb.toFixed(0)}MB`;
}

function validateUploadCandidate(filePath, fileSize, maxBytes) {
  const ext = path.extname(filePath).toLowerCase();

  if (fileSize > maxBytes) {
    throw new Error(
      `File exceeds maximum upload size (${formatBytes(fileSize)} > ${formatBytes(maxBytes)}). ` +
      'Please use a file smaller than 500MB.',
    );
  }

  if (!ext) {
    throw new Error('File has no extension. Please use a standard image/video/audio/text file and check the suffix.');
  }

  if (BLOCKED_UPLOAD_EXTS.has(ext)) {
    throw new Error(`Disallowed file extension "${ext}". Please upload a valid image/video/audio/text file and check the suffix.`);
  }

  if (!ALLOWED_UPLOAD_EXTS.has(ext)) {
    throw new Error(`Unsupported file extension "${ext}". Please upload a valid image/video/audio/text file and check the suffix.`);
  }
}

export async function uploadLocalFileToPublicUrl(ctx, localPathInput, options = {}) {
  const {
    apiPath = DEFAULT_UPLOAD_API_PATH,
    batchNo = makeUploadBatchNo(),
    fixed = false,
    timeoutMs = Number(ctx.requestTimeoutMs) || 60_000,
    maxBytes = DEFAULT_UPLOAD_MAX_BYTES,
  } = options;

  const localPath = normalizeLocalFilePath(localPathInput);
  if (!localPath) {
    throw new Error(`Invalid local path: ${localPathInput}`);
  }

  const stat = await fs.stat(localPath);
  if (!stat.isFile()) {
    throw new Error(`Local path is not a file: ${localPathInput}`);
  }
  validateUploadCandidate(localPath, stat.size, maxBytes);

  const fileBuffer = await fs.readFile(localPath);
  const fileName = path.basename(localPath);
  const mimeType = inferMimeTypeByExtension(localPath);

  const form = new FormData();
  form.append('file', new Blob([fileBuffer], { type: mimeType }), fileName);
  form.append('batch_no', batchNo);
  form.append('fixed', String(Boolean(fixed)));

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);

  let res;
  try {
    const defaultOfficialDomains = ['api.weryai.com', 'api-growth-agent.weryai.com'];
    const uploadUrl = new URL(`${ctx.baseUrl}${apiPath}`);
    if (!defaultOfficialDomains.includes(uploadUrl.hostname) && !process.env.WERYAI_ALLOW_INSECURE_UPLOAD) {
        console.warn(`[SECURITY WARNING] Uploading local file to non-official domain: ${uploadUrl.hostname}. Set WERYAI_ALLOW_INSECURE_UPLOAD=1 to suppress this warning if you trust this endpoint.`);
    }

    res = await fetch(uploadUrl, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${ctx.apiKey}`,
      },
      body: form,
      signal: controller.signal,
    });
  } catch (err) {
    clearTimeout(timer);
    if (err.name === 'AbortError') {
      throw new Error(`Upload timeout after ${timeoutMs}ms: ${localPathInput}`);
    }
    throw err;
  }
  clearTimeout(timer);

  let data;
  try {
    data = await res.json();
  } catch {
    throw new Error(`Upload failed with non-JSON response (HTTP ${res.status}).`);
  }

  const wrapped = { httpStatus: res.status, ...data };
  if (!isApiSuccess(wrapped)) {
    const apiErr = formatApiError(wrapped);
    throw new Error(apiErr.errorMessage || `Upload failed (HTTP ${res.status}).`);
  }

  const uploadedUrl = extractUploadUrl(wrapped);
  if (!uploadedUrl) {
    throw new Error('Upload succeeded but data.object_url_list[0] is missing.');
  }

  return uploadedUrl;
}

export async function resolvePublicUrlFromSource(ctx, source, options = {}) {
  if (typeof source !== 'string' || source.trim().length === 0) {
    throw new Error('media source must be a non-empty string.');
  }

  if (isRemoteUrl(source)) return source;

  return uploadLocalFileToPublicUrl(ctx, source, options);
}

export async function resolvePublicUrlsFromSources(ctx, sources, options = {}) {
  return Promise.all((sources || []).map((source) => resolvePublicUrlFromSource(ctx, source, options)));
}

import { log, sleep } from './client.js';
import { hasTaskOutput, normalizeBatchPhase, normalizeTaskCollection, normalizeTaskResult, toPhase } from './normalize.js';
import { isApiSuccess } from './errors.js';

export function resolvePollIntervalMs(ctx, elapsedMs, options = {}) {
  const configured = Number(ctx?.pollIntervalMs);
  if (Number.isFinite(configured) && configured >= 0) {
    return configured;
  }

  const profile = options.pollProfile || ctx?.pollProfile || 'standard';
  if (profile === 'fast') {
    if (elapsedMs < 30_000) return 2_000;
    if (elapsedMs < 120_000) return 4_000;
    return 6_000;
  }
  if (profile === 'slow') {
    if (elapsedMs < 30_000) return 6_000;
    if (elapsedMs < 120_000) return 10_000;
    return 15_000;
  }

  if (elapsedMs < 30_000) return 3_000;
  if (elapsedMs < 120_000) return 6_000;
  return 10_000;
}

export async function pollSubmittedTasks(client, options) {
  const { batchId, taskIds, allowBatch = false } = options;
  if (!Array.isArray(taskIds) || taskIds.length === 0) {
    return {
      ok: false,
      phase: 'failed',
      errorCode: 'PROTOCOL',
      errorCategory: 'server',
      errorTitle: 'Unexpected API response',
      retryable: false,
      field: 'task_ids',
      hint: 'The API reported success but did not return task IDs. Inspect the raw response before retrying.',
      errorMessage: 'API returned success but no task_ids.',
    };
  }
  if (taskIds.length > 1) {
    return batchId && allowBatch
      ? pollBatch(client, options)
      : pollMultipleTasks(client, options);
  }
  return pollSingleTask(client, { ...options, taskId: taskIds[0] });
}

export async function pollSingleTask(client, options) {
  const { taskId, batchId = null, taskIds = taskId ? [taskId] : [], ctx, outputKey, outputLabel, pollProfile } = options;
  const start = Date.now();

  while (true) {
    const elapsed = Date.now() - start;
    if (elapsed >= ctx.pollTimeoutMs) {
      return {
        ok: false,
        phase: 'failed',
        batchId,
        taskIds,
        taskId,
        taskStatus: 'unknown',
        [outputKey]: null,
        errorCode: 'TIMEOUT',
        errorCategory: 'timeout',
        errorTitle: 'Polling timed out',
        retryable: true,
        field: null,
        hint: 'The task may still be running. Use the status command to inspect the existing task before submitting a new one.',
        errorMessage: `Poll timeout after ${Math.round(elapsed / 1000)}s.`,
      };
    }

    await sleep(resolvePollIntervalMs(ctx, elapsed, { pollProfile }));

    let res;
    try {
      res = await client.get(`/v1/generation/${taskId}/status`, { retries: 3 });
    } catch (err) {
      log(`Warning: poll query failed (${err.message}), will retry next interval.`);
      continue;
    }

    if (!isApiSuccess(res)) {
      log(`Warning: poll returned status ${res.status}, will retry next interval.`);
      continue;
    }

    const task = normalizeTaskResult(res.data);
    const phase = toPhase(task.taskStatus);
    const missingOutputs = phase === 'completed' && !hasTaskOutput(task, outputKey);
    const elapsedSec = Math.round((Date.now() - start) / 1000);
    log(`Polling ${taskId}... status: ${task.taskStatus} (${elapsedSec}s elapsed)`);

    if (phase === 'completed' || phase === 'failed') {
      return {
        ok: phase === 'completed' && !missingOutputs,
        phase: missingOutputs ? 'failed' : phase,
        batchId,
        taskIds,
        taskId: task.taskId,
        taskStatus: task.taskStatus,
        [outputKey]: task[outputKey],
        lyrics: task.lyrics,
        coverUrl: task.coverUrl,
        balance: null,
        errorCode: phase === 'failed' || missingOutputs ? 'TASK_FAILED' : null,
        errorCategory: phase === 'failed' || missingOutputs ? 'task' : null,
        errorTitle: phase === 'failed'
          ? 'Task failed'
          : missingOutputs
            ? `Missing ${outputLabel} output`
            : null,
        retryable: phase === 'failed' || missingOutputs ? false : null,
        field: null,
        hint: phase === 'failed' || missingOutputs ? 'Check the existing task state and parameters before retrying.' : null,
        errorMessage: missingOutputs
          ? `Task reached a completed state but returned no ${outputLabel} URLs.`
          : phase === 'failed'
            ? (task.msg || 'Task failed')
            : null,
      };
    }
  }
}

export async function pollMultipleTasks(client, options) {
  const { taskIds, ctx, outputKey, outputLabel, pollProfile } = options;
  const start = Date.now();

  while (true) {
    const elapsed = Date.now() - start;
    if (elapsed >= ctx.pollTimeoutMs) {
      return {
        ok: false,
        phase: 'failed',
        batchId: null,
        taskIds,
        tasks: null,
        errorCode: 'TIMEOUT',
        errorCategory: 'timeout',
        errorTitle: 'Polling timed out',
        retryable: true,
        field: null,
        hint: 'The tasks may still be running. Inspect the existing task IDs before submitting a new batch.',
        errorMessage: `Poll timeout after ${Math.round(elapsed / 1000)}s.`,
      };
    }

    await sleep(resolvePollIntervalMs(ctx, elapsed, { pollProfile }));

    const tasks = [];
    let shouldRetry = false;

    for (const taskId of taskIds) {
      let res;
      try {
        res = await client.get(`/v1/generation/${taskId}/status`, { retries: 3 });
      } catch (err) {
        log(`Warning: poll query failed for ${taskId} (${err.message}), will retry next interval.`);
        shouldRetry = true;
        break;
      }

      if (!isApiSuccess(res)) {
        log(`Warning: poll returned status ${res.status} for ${taskId}, will retry next interval.`);
        shouldRetry = true;
        break;
      }

      tasks.push(normalizeTaskResult(res.data));
    }

    if (shouldRetry) {
      continue;
    }

    const phase = normalizeBatchPhase(tasks, { outputKey });
    const elapsedSec = Math.round((Date.now() - start) / 1000);
    const summary = tasks.map((task) => `${task.taskId}:${task.taskStatus}`).join(', ');
    log(`Polling tasks... [${summary}] (${elapsedSec}s elapsed)`);

    if (phase === 'completed' || phase === 'failed') {
      return {
        ok: phase === 'completed',
        phase,
        batchId: null,
        taskIds,
        tasks,
        errorCode: phase === 'failed' ? 'TASK_FAILED' : null,
        errorCategory: phase === 'failed' ? 'task' : null,
        errorTitle: phase === 'failed' ? 'Batch failed' : null,
        retryable: phase === 'failed' ? false : null,
        field: null,
        hint: phase === 'failed' ? `Inspect the existing batch and task statuses before retrying.` : null,
        errorMessage: phase === 'failed'
          ? `One or more tasks failed or returned no ${outputLabel} URLs.`
          : null,
      };
    }
  }
}

export async function pollBatch(client, options) {
  const { batchId, taskIds, ctx, outputKey, outputLabel, pollProfile } = options;
  const start = Date.now();

  while (true) {
    const elapsed = Date.now() - start;
    if (elapsed >= ctx.pollTimeoutMs) {
      return {
        ok: false,
        phase: 'failed',
        batchId,
        taskIds,
        tasks: null,
        errorCode: 'TIMEOUT',
        errorCategory: 'timeout',
        errorTitle: 'Polling timed out',
        retryable: true,
        field: null,
        hint: 'The batch may still be running. Inspect the existing batch before submitting a new one.',
        errorMessage: `Poll timeout after ${Math.round(elapsed / 1000)}s.`,
      };
    }

    await sleep(resolvePollIntervalMs(ctx, elapsed, { pollProfile }));

    let res;
    try {
      res = await client.get(`/v1/generation/batch/${batchId}/status`, { retries: 3 });
    } catch (err) {
      log(`Warning: batch poll failed (${err.message}), will retry next interval.`);
      continue;
    }

    if (!isApiSuccess(res)) {
      log(`Warning: batch poll returned status ${res.status}, will retry next interval.`);
      continue;
    }

    const tasks = normalizeTaskCollection(res.data);
    const phase = normalizeBatchPhase(tasks, { outputKey });
    const elapsedSec = Math.round((Date.now() - start) / 1000);
    const summary = tasks.map((task) => task.taskStatus).join(', ');
    log(`Polling batch ${batchId}... [${summary}] (${elapsedSec}s elapsed)`);

    if (phase === 'completed' || phase === 'failed') {
      return {
        ok: phase === 'completed',
        phase,
        batchId,
        taskIds,
        tasks,
        errorCode: phase === 'failed' ? 'TASK_FAILED' : null,
        errorCategory: phase === 'failed' ? 'task' : null,
        errorTitle: phase === 'failed' ? 'Batch failed' : null,
        retryable: phase === 'failed' ? false : null,
        field: null,
        hint: phase === 'failed' ? `Inspect the existing batch and task statuses before retrying.` : null,
        errorMessage: phase === 'failed'
          ? `One or more tasks in the batch failed or returned no ${outputLabel} URLs.`
          : null,
      };
    }
  }
}

const AUDIO_CAPABLE_MODEL_KEYS = new Set([
  'WERYDANCE_2_0',
  'DOUBAO_1_5_PRO',
  'KLING_V3_0_STA',
  'KLING_V3_0_PRO',
  'KLING_V2_6_PRO',
  'VIDU_Q3',
  'VEO_3',
  'VEO_3_FAST',
  'VEO_3_1',
  'VEO_3_1_FAST',
  'CHATBOT_VEO_3_1_FAST',
]);

export function isAudioCapableModelKey(modelKey) {
  if (!modelKey || typeof modelKey !== 'string') return false;
  return AUDIO_CAPABLE_MODEL_KEYS.has(modelKey.trim());
}

export function resolveDefaultGenerateAudio(input, modelKey) {
  const userAudio = input?.generate_audio ?? input?.generateAudio;
  if (userAudio != null) {
    return String(userAudio).toLowerCase() === 'true';
  }
  return isAudioCapableModelKey(modelKey);
}

