  return {
    ok: true,
    phase: 'submitted',
    batchId: data.batch_id ?? null,
    taskIds,
    taskId: taskIds[0] ?? null,
    taskStatus: null,
    videos: null,
    balance: null,
    requestSummary: buildRequestSummary(resolvedBody, effectiveMode),
    errorCode: null,
    errorMessage: null,
  };
